CREATE TABLE "BusinessSetting" ("key" TEXT NOT NULL PRIMARY KEY, "value" JSONB NOT NULL, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "Category" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "slug" TEXT NOT NULL, "displayOrder" INTEGER NOT NULL, "available" BOOLEAN NOT NULL DEFAULT true);
CREATE UNIQUE INDEX "Category_slug_key" ON "Category"("slug");
CREATE TABLE "Product" ("id" TEXT NOT NULL PRIMARY KEY, "categoryId" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "priceCents" INTEGER NOT NULL, "imagePath" TEXT, "available" BOOLEAN NOT NULL DEFAULT true, "displayOrder" INTEGER NOT NULL, CONSTRAINT "Product_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "ProductVariant" ("id" TEXT NOT NULL PRIMARY KEY, "productId" TEXT NOT NULL, "name" TEXT NOT NULL, "priceCents" INTEGER NOT NULL, CONSTRAINT "ProductVariant_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "ProductExtra" ("id" TEXT NOT NULL PRIMARY KEY, "productId" TEXT NOT NULL, "name" TEXT NOT NULL, "priceCents" INTEGER NOT NULL, CONSTRAINT "ProductExtra_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "Order" ("id" TEXT NOT NULL PRIMARY KEY, "customerName" TEXT NOT NULL, "customerPhone" TEXT NOT NULL, "notes" TEXT, "status" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "OrderItem" ("id" TEXT NOT NULL PRIMARY KEY, "orderId" TEXT NOT NULL, "productId" TEXT NOT NULL, "productName" TEXT NOT NULL, "unitPriceCents" INTEGER NOT NULL, "quantity" INTEGER NOT NULL, "selections" JSONB, CONSTRAINT "OrderItem_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
